program(1.3)
[buildInfo = dict<string, string>({})]
{
  func main<ios18>(tensor<fp16, [1, 64, 256]> x) {
    tensor<int32, [1]> axs = const()[name = string("axs"), val = tensor<int32, [1]>([-1])];
    tensor<fp16, [1, 64, 256]> n1 = layer_norm(x = x, axes = axs, epsilon = fp32(0.00001))[name = string("n1")];
    bool f = const()[name = string("f"), val = bool(false)];
    bool t = const()[name = string("t"), val = bool(true)];
    tensor<fp16, [1, 64, 64]> m2 = matmul(transpose_x = f, transpose_y = t, x = n1, y = n1)[name = string("m2")];
    fp16 sc = const()[name = string("sc"), val = fp16(0x1p-3)];
    tensor<fp16, [1, 64, 64]> p3 = mul(x = m2, y = sc)[name = string("p3")];
    int32 ax = const()[name = string("ax"), val = int32(-1)];
    tensor<fp16, [1, 64, 64]> s4 = softmax(x = p3, axis = ax)[name = string("s4")];
    tensor<fp16, [1, 64, 256]> m5 = matmul(transpose_x = f, transpose_y = f, x = s4, y = n1)[name = string("m5")];
    tensor<fp16, [1, 64, 256]> a6 = add(x = x, y = m5)[name = string("a6")];
    tensor<fp16, [1, 64, 256]> n7 = layer_norm(x = a6, axes = axs, epsilon = fp32(0.00001))[name = string("n7")];
    tensor<fp16, [1024, 256]> c8 = const()[name = string("c8"), val = tensor<fp16, [1024, 256]>(BLOBFILE(path = string("@model_path/weights.bin"), offset = uint64(64)))];
    tensor<fp16, [1, 64, 1024]> m9 = matmul(transpose_x = f, transpose_y = t, x = n7, y = c8)[name = string("m9")];
    tensor<fp16, [1, 64, 1024]> g10 = gelu(x = m9, mode = string("EXACT"))[name = string("g10")];
    tensor<fp16, [256, 1024]> c11 = const()[name = string("c11"), val = tensor<fp16, [256, 1024]>(BLOBFILE(path = string("@model_path/weights.bin"), offset = uint64(88)))];
    tensor<fp16, [1, 64, 256]> m12 = matmul(transpose_x = f, transpose_y = t, x = g10, y = c11)[name = string("m12")];
    tensor<fp16, [1, 64, 256]> a13 = add(x = a6, y = m12)[name = string("a13")];
  } -> (a13);
}
